/* AI Build Lab — buildless, account-free classroom activities. */
(() => {
'use strict';
const lessons=window.LESSONS, KEY='ens-ai-build-lab-v1';
const routes={guided:'Guided',independent:'Independent',stretch:'Stretch'};
const strandNames={CU:'AI Conceptual Understanding',SD:'AI Solution Design & Development',CE:'Critical Evaluation & Informed Interaction',GE:'Ethics & Governance',Integration:'All four ADEK strands'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({version:1,route:'guided',settings:{large:false,contrast:false,spacing:false},answers:{},board:{},tools:{},updated:null});
let state=fresh(),storageOK=true,toastTimer,filter={q:'',type:'all',strand:'all',reserve:false},model=null;
const toolKeys=['prompt.goal','prompt.inventory','prompt.gap','prompt.vehicle','prompt.sketch','prompt.format','risk.name','risk.who','risk.likelihood','risk.impact','risk.action','bridge.gap','bridge.vehicle','bridge.trial1','bridge.trial2','bridge.trial3','bridge.change','bridge.retest'];
function cleanState(raw){
 if(!raw||raw.version!==1||typeof raw!=='object')throw Error('This is not an AI Build Lab backup.');
 const n=fresh(),txt=x=>typeof x==='string'?x.slice(0,20000):'';
 if(routes[raw.route])n.route=raw.route;
 for(const k of Object.keys(n.settings))n.settings[k]=raw.settings?.[k]===true;
 for(const l of lessons){const a=raw.answers?.[l.id];if(!a||typeof a!=='object')continue;const fields={};for(const f of [...l.fields,{id:'extension'},{id:'exit'},{id:'practiceReason'}])fields[f.id]=txt(a.fields?.[f.id]);n.answers[l.id]={fields,checks:Array.from({length:l.originalSteps.length},(_,i)=>a.checks?.[i]===true),oral:l.fields.filter(f=>Array.isArray(a.oral)&&a.oral.includes(f.id)).map(f=>f.id),exitOral:a.exitOral===true,ready:a.ready===true,route:routes[a.route]?a.route:n.route,stage:Number.isInteger(a.stage)?Math.max(0,Math.min(3,a.stage)):0,taskIndex:Number.isInteger(a.taskIndex)?Math.max(0,Math.min(l.originalSteps.length-1,a.taskIndex)):0,fieldIndex:Number.isInteger(a.fieldIndex)?Math.max(0,Math.min(l.fields.length,a.fieldIndex)):0,cardIndex:Number.isInteger(a.cardIndex)?Math.max(0,Math.min(100,a.cardIndex)):0,choice:Number.isInteger(a.choice)&&a.choice>=0&&a.choice<3?a.choice:null};}
 for(const k of ['need','questions','existing','findings'])n.board[k]=txt(raw.board?.[k]);
 for(const k of toolKeys)n.tools[k]=txt(raw.tools?.[k]);
 n.updated=typeof raw.updated==='string'?raw.updated:null;return n;
}
try{const saved=localStorage.getItem(KEY);if(saved)state=cleanState(JSON.parse(saved));}catch(e){storageOK=false;}
const main=document.getElementById('main');
function answer(id){if(!state.answers[id])state.answers[id]={fields:{},checks:[],oral:[],exitOral:false,ready:false,route:state.route,stage:0,taskIndex:0,fieldIndex:0,cardIndex:0,choice:null};return state.answers[id];}
function toast(t){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=t;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4800);}
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}document.getElementById('save-state').textContent=storageOK?'Saved on this device':'Not saved — export a backup';updateProgress();}
function updateProgress(){const n=lessons.filter(l=>l.id<=22&&state.answers[l.id]?.ready).length;document.getElementById('progress-label').textContent=`${n} of 22 lessons`;document.getElementById('course-progress').value=n;}
function settings(){for(const [k,c] of [['large','large-text'],['contrast','contrast'],['spacing','spaced']]){document.documentElement.classList.toggle(c,state.settings[k]);document.getElementById(`${k}-setting`).checked=state.settings[k];}}
const field=(id,label,value,frame='',extra='')=>`<div class="field"><label for="${id}">${esc(label)}</label>${frame?`<div class="sentence">${esc(frame)}</div>`:''}<textarea id="${id}" ${extra}>${esc(value)}</textarea></div>`;
const source=l=>l.page?`<a class="source-link" href="resources/adek-grade6-teacher-pack.pdf#page=${l.page}" target="_blank" rel="noopener">ADEK Teacher Pack · PDF p. ${l.page} ↗</a>`:'<span class="small">Additional MYP practical lesson</span>';
const footer=()=>'<div class="footer-source">Based on the supplied Grade 6 ADEK Teacher Pack v4. Student activities here are classroom adaptations. All live AI use is teacher-operated; practice outputs are labelled simulations.</div>';
function icon(kind){const paths={gear:'<path d="M27 9h10l2 8 7 4 8-2 5 9-6 6v8l6 6-5 9-8-2-7 4-2 8H27l-2-8-7-4-8 2-5-9 6-6v-8l-6-6 5-9 8 2 7-4z"/><circle cx="32" cy="34" r="10"/>',data:'<rect x="8" y="11" width="21" height="20" rx="4"/><rect x="35" y="11" width="21" height="20" rx="4"/><rect x="8" y="37" width="21" height="20" rx="4"/><path d="M38 47l6 6 12-14"/>',eye:'<path d="M5 32s10-17 27-17 27 17 27 17-10 17-27 17S5 32 5 32z"/><circle cx="32" cy="32" r="9"/>',check:'<circle cx="32" cy="32" r="24"/><path d="M19 32l9 9 18-21"/>',prompt:'<rect x="8" y="11" width="48" height="37" rx="7"/><path d="M17 48v10l13-10M19 23h26M19 33h18"/>',hand:'<path d="M17 48V27a4 4 0 018 0v10-22a4 4 0 018 0v22-26a4 4 0 018 0v26-20a4 4 0 018 0v24c0 11-7 18-16 18-8 0-13-4-17-11l-7-12a4 4 0 016-5l8 10"/>',plan:'<rect x="12" y="10" width="40" height="48" rx="5"/><path d="M22 22h20M22 33h20M22 44h12"/>',target:'<circle cx="32" cy="32" r="25"/><circle cx="32" cy="32" r="15"/><circle cx="32" cy="32" r="5"/>',shield:'<path d="M32 6L55 15v17c0 14-12 23-23 27C21 55 9 46 9 32V15z"/><path d="M21 31l8 8 16-18"/>',test:'<rect x="8" y="12" width="48" height="41" rx="5"/><path d="M8 26h48M24 26v27M40 26v27M8 39h48"/>',build:'<path d="M8 29h48v26H8zM17 29V17h12v12m8 0V17h12v12M8 41h48M25 41v14"/>',flag:'<path d="M15 58V8m0 3c13-10 22 10 37 0v27c-15 10-24-10-37 0"/>',question:'<circle cx="32" cy="32" r="25"/><path d="M23 25a9 9 0 0118 0c0 7-9 8-9 15m0 7v1"/>',repeat:'<path d="M49 19a23 23 0 00-37 7M49 6v14H35M15 45a23 23 0 0037-7M15 58V44h14"/>'};return `<svg class="learning-icon" viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${paths[kind]||paths.build}</svg>`;}
function visualDiagram(l){const id=l.id;const tile=(i,title,sub='',cls='')=>`<div class="picture-tile ${cls}">${icon(i)}<strong>${title}</strong>${sub?`<span>${sub}</span>`:''}</div>`;
 if([1,2,3].includes(id))return `<div class="picture-pair">${tile('gear','Fixed rules','Person writes the steps')}${tile('data','Learning','Examples shape a pattern','wine-picture')}</div>`;
 if(id===4)return `<div class="picture-pair">${tile('data','TRAIN','8–10 examples per class')}${tile('test','TEST','3 new examples per class','wine-picture')}</div><div class="picture-caption">Different cards. No personal data.</div>`;
 if([5,6].includes(id))return `<div class="picture-trio">${tile('target','Goal','What to do')}${tile('build','Context','Facts and pieces')}${tile('plan','Format','How it looks')}</div>`;
 if([7,8].includes(id))return `<div class="verdict-picture"><div class="verdict green">✓<strong>Correct</strong><span>Matches</span></div><div class="verdict rose">×<strong>Incorrect</strong><span>Conflicts</span></div><div class="verdict amber">?<strong>Unclear</strong><span>Need more</span></div></div>`;
 if([9,10].includes(id))return `<div class="picture-trio">${tile('question','Risk','What could go wrong?')}${tile('hand','User','Who is affected?')}${tile('shield','Action','How can we reduce it?')}</div>`;
 if([11,12,19,20].includes(id))return `<div class="picture-four">${tile('gear','Understand')}${tile('prompt','Create')}${tile('eye','Check')}${tile('shield','Care')}</div>`;
 if(id===13)return `<div class="picture-four">${tile('target','Goal')}${tile('prompt','Inputs')}${tile('eye','Checks')}${tile('shield','Risk')}</div><div class="picture-caption">Show your plan to your teacher before building.</div>`;
 if(id===14)return `<div class="picture-pair">${tile('check','Normal input','All facts are here')}${tile('question','Tricky input','The gap is missing','wine-picture')}</div>`;
 if([15,17].includes(id))return `<div class="picture-pair">${tile('prompt','Before','Something needs fixing')}${tile('repeat','After','Change → check again','wine-picture')}</div>`;
 if(id===16)return `<div class="six-cases">${[1,2,3,4,5,6].map(n=>`<span><b>${n}</b><small>Check this case</small></span>`).join('')}</div><div class="picture-caption">Keep every result — including failures.</div>`;
 if(id===18)return `<div class="retest-picture"><span>BEFORE</span>${[1,2,3,4,5].map(n=>`<b>${n}</b>`).join('')}<span>AFTER</span>${[1,2,3,4,5].map(n=>`<b>${n}</b>`).join('')}</div><div class="picture-caption">Same cases. Same checks. Compare.</div>`;
 if(id===21)return '<img class="stage-bridge" src="assets/bridge-hero.svg" alt="Illustration of a model bridge carrying a toy vehicle. Check your own design with your teacher.">';
 if(id===22)return `<div class="picture-trio">${[1,2,3].map(n=>tile('test','Trial '+n,'Record the real result')).join('')}</div>`;
 return `<div class="picture-pair">${tile('plan','Choose one task')}${tile('check','Show your evidence')}</div>`;
}
function home(){const next=lessons.find(l=>l.id<=22&&!state.answers[l.id]?.ready)||lessons[0];return `<div class="breadcrumb">Grade 6 Design · AI Build Battle</div><section class="hero visual-home"><div class="hero-copy"><div class="eyebrow">YOUR MISSION</div><h1>Can you<br><span>bridge the gap?</span></h1><p>Build it. Test it. Make it better.</p><a class="btn big-start" href="#lesson/${next.id}">Let's go ${icon('flag')}</a><a class="text-link" href="#lessons">Choose a lesson →</a></div><img class="hero-art" src="assets/bridge-hero.svg" alt="A model bridge and toy rescue vehicle — the classroom build challenge."></section><div class="mission-strip"><div>${icon('eye')}<strong>LOOK</strong><span>Spot the idea</span></div><div>${icon('hand')}<strong>TRY</strong><span>Make a choice</span></div><div>${icon('build')}<strong>DO</strong><span>One task at a time</span></div><div>${icon('flag')}<strong>SHOW</strong><span>Share your thinking</span></div></div><div class="section-heading"><h2>Ready to explore?</h2><a class="small" href="#teacher">Teacher area ↗</a></div><div class="grid"><a class="picture-link" href="#lessons">${icon('plan')}<strong>My lessons</strong><span>Pick your next challenge →</span></a><a class="picture-link" href="#tools">${icon('build')}<strong>My workbench</strong><span>Try a tool →</span></a><a class="picture-link" href="#board">${icon('eye')}<strong>My research board</strong><span>Find out before you build →</span></a></div><p class="quiet-footer">Your work stays on this device. Export it from <a href="#evidence">My evidence</a> before switching iPads.</p>`;}
function lessonCards(list){return list.map(l=>`<article class="card lesson-card visual-card ${l.type==='Lab'?'lab-card':''}"><div class="tag-row"><span class="tag">${l.type==='Reserve'?'RESERVE':'LESSON '+String(l.id).padStart(2,'0')}</span><span class="small">${l.type}</span></div><div class="lesson-picture-small">${icon(l.id<=4?'data':l.id<=6?'prompt':l.id<=10?'eye':l.id<=14?'plan':l.id<=18?'test':'build')}</div><h3>${esc(l.short)}</h3><div class="card-bottom"><a class="btn secondary small-btn" href="#lesson/${l.id}">Let's go →</a><span class="small">${state.answers[l.id]?.ready?'✓ Ready':'Week '+l.week}</span></div></article>`).join('');}

function lessonsPage(){return `<div class="page-heading"><div><div class="eyebrow">CORE → LAB → BUILD</div><h1>Your lessons</h1><p>Choose a challenge. Take it one step at a time.</p></div><a class="btn secondary" href="#evidence">My evidence</a></div><div class="filters"><input id="lesson-search" type="search" aria-label="Search lessons" placeholder="Find a topic or lesson…" value="${esc(filter.q)}"><select id="type-filter" aria-label="Filter by lesson type">${['all','Core','Lab','Practical'].map(x=>`<option value="${x}" ${filter.type===x?'selected':''}>${x==='all'?'All lesson types':x}</option>`).join('')}</select><select id="strand-filter" aria-label="Filter by ADEK strand">${['all','CU','SD','CE','GE','Integration'].map(x=>`<option value="${x}" ${filter.strand===x?'selected':''}>${x==='all'?'All strands':x==='Integration'?'All four together':strandNames[x]}</option>`).join('')}</select><label><input type="checkbox" id="reserve-filter" ${filter.reserve?'checked':''}> Reserve lessons</label></div><div id="result-count" class="result-count" aria-live="polite"></div><div class="grid" id="lesson-results"></div>${footer()}`;}
function filterLessons(){const list=lessons.filter(l=>(filter.reserve||l.type!=='Reserve')&&(filter.type==='all'||l.type===filter.type)&&(filter.strand==='all'||l.strand===filter.strand)&&`${l.id} ${l.title} ${l.short} ${l.teach}`.toLowerCase().includes(filter.q.toLowerCase()));document.getElementById('lesson-results').innerHTML=list.length?lessonCards(list):'<div class="empty">No lessons match. Try another word or reset the filters.</div>';document.getElementById('result-count').textContent=`${list.length} lessons shown · 20 ADEK lessons + 2 practical lessons + 2 reserves available`;}
function stageSpeak(l){const a=answer(l.id),st=a.stage||0;if(st===0)return `${l.short}. ${l.visual.bite}`;if(st===1)return `${l.visual.question}. ${l.visual.options.map((x,i)=>(i+1)+'. '+x).join('. ')}. ${a.choice!=null?l.visual.feedback:''}`;if(st===2)return `Your task ${a.taskIndex+1}. ${l.visual.steps[a.taskIndex||0]}`;const f=l.fields[a.fieldIndex||0];return f?`${f.label}. ${f.frame}`:`Exit question. ${l.exit}`;}
function lessonPage(l){const a=answer(l.id),r=a.route||state.route,st=a.stage||0,v=l.visual,idx=Math.min(a.taskIndex||0,v.steps.length-1),fi=Math.min(a.fieldIndex||0,l.fields.length),names=['Look','Try','Do','Show'],icons=['eye','hand','build','flag'];
 let body='';
 if(st===0)body=`<section class="stage-panel"><div class="stage-lead"><span class="stage-kicker">LOOK</span><h2>${[1,2,3].includes(l.id)?'Two ways to decide':l.id===4?'Train first. Test with new examples.':l.id===16?'Six cases. Six checks.':l.id===18?'Does your change really help?':'See the big idea'}</h2></div><div class="lesson-picture">${visualDiagram(l)}</div><p class="bite">${esc(v.bite)}</p><div class="stage-controls"><button class="btn big-start" data-action="stage" data-id="${l.id}" data-stage="1">Try it →</button></div></section>`;
 if(st===1)body=`<section class="stage-panel"><div class="stage-lead"><span class="stage-kicker">TRY</span><h2>${esc(v.question)}</h2></div><div class="choice-grid">${v.options.map((x,i)=>`<button class="answer-choice ${a.choice===i?'picked':''}" data-action="visual-choice" data-id="${l.id}" data-choice="${i}" aria-pressed="${a.choice===i}"><span class="choice-letter">${['A','B','C'][i]}</span><span>${esc(x)}</span>${a.choice===i?'<b aria-hidden="true">✓</b>':''}</button>`).join('')}</div>${a.choice!=null?`<div class="choice-feedback ${a.choice===v.correct?'correct':'retry'}" role="status"><strong>${a.choice===v.correct?'You found the evidence!':'Have another look.'}</strong><p>${esc(v.feedback)}</p></div>`:'<p class="tap-hint">Tap a choice. Then check the reason.</p>'}${r!=='guided'?field('practice-reason','What is your reason?',a.fields.practiceReason||'','',`data-answer="practiceReason" data-lesson="${l.id}"`):''}<div class="stage-controls"><button class="btn secondary" data-action="stage" data-id="${l.id}" data-stage="0">← Look again</button><button class="btn big-start" data-action="stage" data-id="${l.id}" data-stage="2">My task →</button></div></section>`;
 if(st===2){const chunks=(l.materials||[]).flatMap(m=>m.body.split(/(?<=[.!?])\s+/).map((text,n)=>({title:m.title,text}))).filter(x=>x.text.trim());const ci=Math.min(a.cardIndex||0,Math.max(0,chunks.length-1));const c=chunks[ci];body=`<section class="stage-panel"><div class="task-heading"><span class="stage-kicker">DO</span><span class="pill-counter" id="check-count">${a.checks.filter(Boolean).length}/${v.steps.length} done</span></div><div class="task-card"><span class="task-number">${idx+1}</span><h2>${esc(v.steps[idx])}</h2><div class="task-picture">${icon(idx===v.steps.length-1?'flag':l.id===4?'data':l.id>=21?'build':'hand')}</div>${r==='guided'?'<p class="tap-hint">Do this step. Show or tell a partner.</p>':''}${a.checks[idx]?`<button class="text-link" data-action="task-undo" data-id="${l.id}">I need to redo this</button>`:''}</div><div class="stage-controls"><button class="btn secondary" data-action="task-prev" data-id="${l.id}" ${idx===0?'disabled':''}>← Previous step</button><button class="btn big-start" data-action="task-done" data-id="${l.id}">${a.checks[idx]?'Done — next →':'I did this ✓'}</button></div><div class="task-dots" aria-label="Task progress">${v.steps.map((s,i)=>`<button aria-label="Task ${i+1}${a.checks[i]?' completed':''}" data-action="task-jump" data-id="${l.id}" data-task="${i}" class="${i===idx?'current':''} ${a.checks[i]?'done':''}">${i+1}</button>`).join('')}</div>${c?`<details class="help-drawer"><summary>${icon('plan')} Need the task cards?</summary><div class="material-card"><span class="small">CARD ${ci+1} OF ${chunks.length} · ${esc(c.title)}</span><p>${esc(c.text)}</p><div class="actions"><button class="btn secondary small-btn" data-action="material-prev" data-id="${l.id}" ${ci===0?'disabled':''}>← Back</button><button class="btn secondary small-btn" data-action="material-next" data-id="${l.id}" data-max="${chunks.length-1}" ${ci===chunks.length-1?'disabled':''}>Next card →</button></div></div></details>`:''}<div class="actions task-tools"><a class="btn secondary" href="#tools/${l.id<=3?'rules':l.id===4?'model':[7,8].includes(l.id)?'triage':[9,10,18].includes(l.id)?'risk':l.id>=21?'bridge':'prompt'}">${icon('build')} Open a tool</a><button class="text-link" data-action="help-prompt">Ask for help</button><button class="text-link" data-action="stage" data-id="${l.id}" data-stage="3">Show my evidence →</button></div></section>`;}
 if(st===3){const f=l.fields[fi],last=!f,oral=last?a.exitOral:a.oral.includes(f.id),k=last?'exit':f.id,label=last?l.exit:f.label,frame=last?'I think ___ because the evidence shows ___.':f.frame;body=`<section class="stage-panel"><div class="task-heading"><span class="stage-kicker">SHOW</span><span class="pill-counter">${fi+1}/${l.fields.length+1}</span></div><div class="show-prompt">${icon(last?'flag':'prompt')}<h2>${esc(label)}</h2></div>${field(last?'exit-answer':'answer-'+k,'My answer or evidence reference',a.fields[k]||'',r==='guided'?frame:'',`data-answer="${k}" data-lesson="${l.id}"`)}<label class="oral visual-oral"><input type="checkbox" ${last?`data-exit-oral="${l.id}"`:`data-oral="${k}" data-lesson="${l.id}"`} ${oral?'checked':''}> I explained it to my teacher. We agreed how to record it.</label>${r!=='guided'?`<details><summary>Help me start</summary><p class="sentence">${esc(frame)}</p></details>`:''}<div class="stage-controls"><button class="btn secondary" data-action="evidence-prev" data-id="${l.id}" ${fi===0?'disabled':''}>← Back</button>${!last?`<button class="btn big-start" data-action="evidence-next" data-id="${l.id}">Next answer →</button>`:`<button class="btn big-start" data-action="ready" data-id="${l.id}">Ready for my teacher ✓</button>`}</div>${last&&r==='stretch'?`<details class="help-drawer extension"><summary>${icon('target')} Your stretch challenge</summary><p>${esc(l.stretch)}</p>${field('extension-answer','My reasoning and evidence',a.fields.extension||'','',`data-answer="extension" data-lesson="${l.id}"`)}</details>`:''}${a.ready?'<div class="choice-feedback correct" role="status"><strong>Ready for teacher review ✓</strong><p>This is your progress record, not a grade.</p></div>':''}</section>`;}
 return `<div class="breadcrumb"><a href="#lessons">My lessons</a> / Lesson ${l.id}</div><div class="lesson-top visual-lesson-top"><div><div class="eyebrow">WEEK ${l.week} · ${l.type.toUpperCase()}</div><h1>${esc(l.short)}</h1></div><div class="actions"><button class="btn secondary small-btn" data-action="speak" data-id="${l.id}">▷ Read this step</button><button class="btn secondary small-btn" data-action="print-lesson" data-id="${l.id}">Print</button></div></div><div class="visual-route"><span>My route</span><div class="segmented" role="group" aria-label="Choose your learning route">${Object.keys(routes).map(k=>`<button data-action="route" data-route="${k}" data-id="${l.id}" class="${r===k?'selected':''}" aria-pressed="${r===k}">${routes[k]}</button>`).join('')}</div></div><nav class="stage-tabs" aria-label="Lesson steps">${names.map((n,i)=>`<button data-action="stage" data-id="${l.id}" data-stage="${i}" class="${st===i?'active':''}" aria-current="${st===i?'step':'false'}">${icon(icons[i])}<span>${i+1}. ${n}</span></button>`).join('')}</nav>${body}<div class="visual-bottom"><a href="#lesson/${Math.max(1,l.id-1)}">← Previous lesson</a><a href="#teacher/${l.id}">Teacher notes ↗</a>${l.id<24?`<a href="#lesson/${l.id+1}">Next lesson →</a>`:'<a href="#evidence">My evidence →</a>'}</div><p class="quiet-footer">Live AI is teacher-operated. Your answers save on this device.</p>`;
}

const toolsList=[['rules','Rules or learning','Classify described systems using evidence.','↔'],['model','Train a small model','Compare a tiny model trained on example lengths.','◈'],['prompt','Prompt builder','Build a reusable guide with input and check slots.','≡'],['triage','Output triage','Judge practice outputs against a reference.','✓'],['risk','Risk matrix','Connect a risk, affected user and mitigation.','▦'],['bridge','Crossing log','Record three real trials and a retest.','⌁']];
function toolsPage(which){const head=`<div class="page-heading"><div><div class="eyebrow">HANDS ON, MINDS ON</div><h1>Your workbench</h1><p>Try an idea, check a result and keep the evidence.</p></div></div>`;if(!which)return head+`<div class="grid">${toolsList.map(t=>`<article class="card"><div class="tool-icon" aria-hidden="true">${t[3]}</div><h3>${t[1]}</h3><p>${t[2]}</p><a class="stretched" href="#tools/${t[0]}">Open tool →</a></article>`).join('')}</div>${footer()}`;return head+`<nav class="tool-tabs" aria-label="Workbench tools">${toolsList.map(t=>`<a href="#tools/${t[0]}" class="${which===t[0]?'active':''}">${t[1]}</a>`).join('')}</nav>`+({rules:rulesTool,model:modelTool,prompt:promptTool,triage:triageTool,risk:riskTool,bridge:bridgeTool}[which]||(()=>'<p>Choose a tool above.</p>'))()+footer();}
function rulesTool(){const cards=[['A timer changes a light after a person-set number of seconds.','rules','The timing rule was written by a person.'],['A model studies labelled shapes, then predicts a label for a new shape.','learning','The decision pattern came from examples.'],['A vehicle follows the same stored turn sequence every time.','rules','Following a stored sequence does not demonstrate learning.']];return `<div class="learning-block"><h2>Look at the decision process</h2><p>Choose the system type, then check your reason. These descriptions tell you how each system works; a product name alone might not.</p>${cards.map((c,i)=>`<div class="rule-card"><strong>Card ${i+1}</strong><p>${c[0]}</p><div class="actions"><button class="btn secondary small-btn" data-action="rule-check" data-correct="${c[1]}" data-choice="rules" data-target="rule-${i}" data-reason="${esc(c[2])}">Fixed rules</button><button class="btn secondary small-btn" data-action="rule-check" data-correct="${c[1]}" data-choice="learning" data-target="rule-${i}" data-reason="${esc(c[2])}">Learning from examples</button></div><p id="rule-${i}" class="small" aria-live="polite"></p></div>`).join('')}<a class="text-link" href="#lesson/1">Record your own reasons in Lesson 1 →</a></div>`;}
function modelTool(){return `<div class="learning-block"><div class="eyebrow">A SMALL LEARNING DEMONSTRATION</div><h2>Learn from piece lengths</h2><p>This numeric model learns the mean length for each labelled class, then predicts the nearest class mean. It is a tiny example of learning from data, not an image-recognition tool.</p><p class="small">The reference labels are Short for lengths below 6 units and Long for 6 or more. The model sees only the training examples; the six held-back test examples stay the same.</p><div class="actions"><button class="btn" data-action="model" data-profile="balanced">Train on varied examples</button><button class="btn secondary" data-action="model" data-profile="narrow">Train on narrow examples</button><button class="btn secondary" data-action="model" data-profile="noisy">Train on a wrong label</button></div><div id="model-result" class="note" aria-live="polite">Choose a training set. Each has eight labelled examples per class. Then compare the six unseen predictions.</div><a class="text-link" href="#lesson/4">Record predictions, explanation and safety in Lesson 4 →</a></div>`;}
function trainModel(profile){const short=[2,2,3,3,4,4,5,5],long=profile==='narrow'?[6,6,6,6,6,6,6,6]:profile==='noisy'?[1,6,7,7,8,8,9,9]:[6,6,7,7,8,8,9,9];const mean=a=>a.reduce((a,b)=>a+b,0)/a.length,s=mean(short),l=mean(long),tests=[2,3,5,7,9,10];const rows=tests.map(x=>{const expected=x<6?'Short':'Long',pred=Math.abs(x-s)<=Math.abs(x-l)?'Short':'Long';return{x,expected,pred,ok:pred===expected};});model={profile,rows};document.getElementById('model-result').innerHTML=`<p><strong>${profile==='balanced'?'Varied':profile==='narrow'?'Narrow':'Noisy'} training set</strong></p><p>Short examples: ${short.join(', ')}. Mean ${s.toFixed(2)}.<br>Long examples: ${long.join(', ')}. Mean ${l.toFixed(2)}.</p><div class="table-wrap"><table><caption>Six held-back examples</caption><thead><tr><th>Length</th><th>Reference label</th><th>Prediction</th><th>Result</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.x}</td><td>${r.expected}</td><td>${r.pred}</td><td>${r.ok?'Correct':'Incorrect'}</td></tr>`).join('')}</tbody></table></div><strong>${rows.filter(r=>r.ok).length}/6 correct</strong><p class="small">${profile==='balanced'?'The varied set handles this test set. It does not prove performance on every possible length.':profile==='narrow'?'The long examples cover only one length. Compare what happened near the boundary.':'One long-labelled example is actually short. Check how the incorrect label changes the learned mean.'} Training and test examples remain separate.</p>`;}
function tf(key,label,type='text',placeholder=''){return `<div class="field"><label for="tool-${key}">${label}</label><input id="tool-${key}" type="${type}" ${type==='number'?'min="0" step="any"':''} data-tool="${key}" value="${esc(state.tools[key]||'')}" placeholder="${esc(placeholder)}"></div>`;}
let promptCursor=0,boardCursor=0;
function promptTool(){const qs=[['prompt.goal','What should your guide help someone do?','Write a short goal.','Help a classmate assemble our model bridge.','target'],['prompt.inventory','Which pieces do you actually have?','Name the pieces, counts and sizes.','Count the real tray — do not use made-up pieces.','build'],['prompt.gap','How wide is the gap?','Use the gap your teacher agreed.','Enter the measurement in cm.','test'],['prompt.vehicle','What size is the vehicle?','Measure its length and width.','The bridge must fit the actual class vehicle.','plan'],['prompt.sketch','What does your approved sketch show?','Name the main parts and connections.','Use the drawing your teacher checked.','eye'],['prompt.format','How should the instructions look?','Choose a format your builder can follow.','Your prompt is text for your teacher to run.','prompt']];const q=qs[promptCursor];return `<div class="tool-layout visual-prompt-layout"><section class="stage-panel"><div class="task-heading"><span class="stage-kicker">BUILD MY PROMPT</span><span class="pill-counter">${promptCursor+1}/6</span></div><div class="show-prompt">${icon(q[4])}<h2>${q[1]}</h2></div><p>${q[2]}</p>${promptCursor===5?`<div class="field"><label for="tool-format">My format</label><select id="tool-format" data-tool="prompt.format"><option value="steps" ${state.tools['prompt.format']!=='table'?'selected':''}>Six short numbered steps</option><option value="table" ${state.tools['prompt.format']==='table'?'selected':''}>Step / material / check table</option></select></div>`:tf(q[0],'My answer',promptCursor===2?'number':'text',q[3])}<p class="tap-hint">${q[3]}</p><div class="stage-controls"><button class="btn secondary" data-action="prompt-prev" ${promptCursor===0?'disabled':''}>← Back</button>${promptCursor<5?'<button class="btn big-start" data-action="prompt-next">Next →</button>':'<button class="btn big-start" data-action="copy-prompt">Copy for my teacher</button>'}</div><details class="help-drawer"><summary>${icon('prompt')} See my full prompt</summary><div class="output pre" id="prompt-preview"></div><button class="btn secondary small-btn" data-action="copy-prompt">Copy prompt</button></details></section><aside class="learning-block prompt-side"><div class="picture-trio">${['target','build','plan'].map((x,i)=>`<div class="picture-tile">${icon(x)}<strong>${['Goal','Context','Format'][i]}</strong></div>`).join('')}</div><p class="quiet-footer">You design the prompt.<br>Your teacher runs the AI.</p><details><summary>Compare two practice outputs</summary><p class="practice-label">These are fixed examples. They do not respond to your prompt.</p><div class="actions"><button class="btn secondary small-btn" data-action="practice-output" data-version="weak">Weak example</button><button class="btn secondary small-btn" data-action="practice-output" data-version="better">Revised example</button></div><div id="practice-output" class="output" style="margin-top:15px">Tap an example.</div></details></aside></div>`;}

function promptText(){const v=k=>state.tools[k]||`[ADD ${k.split('.')[1].toUpperCase()}]`;return `ROLE: Classroom model-building guide.\nGOAL: ${v('prompt.goal')}\nCONTEXT: Inventory ${v('prompt.inventory')}. Required gap ${v('prompt.gap')} cm. Vehicle ${v('prompt.vehicle')}. Approved sketch ${v('prompt.sketch')}.\nRULES: Check all inputs are present and consistent. If a fact is missing or conflicting, reply ASK TEACHER and identify the check. Use only recorded materials. Do not invent exact connections or promise strength. The teacher must verify the output.\nFORMAT: ${state.tools['prompt.format']==='table'?'A step / material / check table, with no more than six steps.':'No more than six short numbered steps.'}\nFINISH: Inventory check; gap and vehicle-fit check; physical crossing test. If a check fails, stop and ask a person.\nPRIVACY: Use non-personal, fictional task information only.`;}
function updatePrompt(){const x=document.getElementById('prompt-preview');if(x)x.textContent=promptText();}
function triageTool(){const cards=[['Reference: six plates, no cardboard.','Output: use eight plates.','incorrect','The count exceeds the inventory. Count the real pieces before use.'],['Reference: six plates, no cardboard.','Output: use six plates, then compare their layout with the approved sketch.','correct','This statement matches the inventory and includes a check; it does not prove the whole bridge will work.'],['Reference: a sketch labels two possible joints.','Output: attach the beam there.','unclear','The connection is not identified. Compare the sketch and ask which joint is meant.'],['Reference: no physical crossing test has been run.','Output: this bridge will definitely carry the vehicle.','incorrect','The certainty claim is unsupported. A physical test is still required.']];return `<div class="learning-block"><h2>Verdict → evidence → action</h2><p>Classify all four practice outputs. Read the feedback, then make your own trust ranking in Lesson 8.</p>${cards.map((c,i)=>`<div class="rule-card"><span class="tag">STATION ${i+1}</span><p><strong>${c[0]}</strong><br>${c[1]}</p><div class="actions">${['correct','incorrect','unclear'].map(v=>`<button class="btn secondary small-btn" data-action="triage-check" data-choice="${v}" data-correct="${c[2]}" data-target="triage-${i}" data-reason="${esc(c[3])}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><p id="triage-${i}" class="small" aria-live="polite"></p></div>`).join('')}<a class="text-link" href="#lesson/8">Record four verdicts and your trust ladder →</a></div>`;}
function riskTool(){return `<div class="tool-layout"><section class="learning-block"><h2>Name the risk</h2>${tf('risk.name','What could go wrong?','text','The guide invents a piece')}${tf('risk.who','Who is affected?','text','The builder cannot finish')}<div class="two-col-fields">${riskSelect('risk.likelihood','Likelihood')}${riskSelect('risk.impact','Impact')}</div>${tf('risk.action','Mitigation and check','text','Compare the guide with the real inventory')}<p class="small">Use an anonymised class record where available. Do not enter anyone’s name or private information.</p></section><section class="learning-block"><h2>Discuss the priority</h2><div id="risk-output" class="output"></div><p class="small">The 1–3 scales are a classroom discussion aid, not official ADEK grade boundaries. Justify the placement; do not let a number replace a reason.</p><a class="text-link" href="#lesson/10">Record the full audit and priority decision →</a><a class="text-link" href="#lesson/18">Record the final safe-and-fair statement →</a></section></div>`;}
function riskSelect(k,label){return `<div class="field"><label for="${k}">${label}</label><select id="${k}" data-tool="${k}"><option value="">Choose…</option>${[1,2,3].map((v,i)=>`<option value="${v}" ${state.tools[k]===String(v)?'selected':''}>${v} · ${['Low','Medium','High'][i]}</option>`).join('')}</select></div>`;}
function updateRisk(){const el=document.getElementById('risk-output');if(!el)return;const a=+state.tools['risk.likelihood'],b=+state.tools['risk.impact'];el.textContent=a&&b?`Likelihood ${a} × impact ${b} = ${a*b}.\nRisk: ${state.tools['risk.name']||'[name the risk]'}.\nAffected user: ${state.tools['risk.who']||'[name the user type]'}.\nAction: ${state.tools['risk.action']||'[choose a mitigation]'}.\nExplain why this placement makes sense and what evidence could change it.`:'Choose a likelihood and impact, then explain the placement.';}
function bridgeTool(){return `<div class="tool-layout"><section class="learning-block"><h2>Record real crossings</h2><p class="small">Use the teacher-agreed tabletop gap and the same toy vehicle and conditions. Leave unknown results blank; the site does not simulate the bridge.</p>${tf('bridge.gap','Actual gap in cm','number','Teacher-agreed measurement')}${tf('bridge.vehicle','Vehicle and constant conditions','text','Describe the same class vehicle')}<div class="table-wrap"><table><thead><tr><th>Trial</th><th>Actual result</th></tr></thead><tbody>${[1,2,3].map(i=>`<tr><td>${i}</td><td><select aria-label="Trial ${i} result" data-tool="bridge.trial${i}"><option value="">Not tested</option><option value="pass" ${state.tools['bridge.trial'+i]==='pass'?'selected':''}>Crossed successfully</option><option value="fail" ${state.tools['bridge.trial'+i]==='fail'?'selected':''}>Did not cross successfully</option></select></td></tr>`).join('')}</tbody></table></div><div id="bridge-score" class="trial-score" aria-live="polite"></div></section><section class="learning-block"><h2>Change one feature</h2>${tf('bridge.change','What changed, and why?','text','Use the actual failure or observation')}${tf('bridge.retest','Retest under the same conditions','text','Record the real result and evidence')}<div class="note">A classroom crossing test does not establish real-world structural safety. Explain what this small test can and cannot show.</div><a class="text-link" href="#lesson/22">Write the evaluation and user impact →</a></section></div>`;}
function updateBridge(){const el=document.getElementById('bridge-score');if(!el)return;const vals=[1,2,3].map(i=>state.tools['bridge.trial'+i]);el.textContent=`${vals.filter(x=>x==='pass').length}/3 successful · ${vals.filter(x=>x==='pass'||x==='fail').length}/3 tested`;}
const boardParts=[['need','A.i','Who needs it, and why?','Name the builder and explain the problem.','My user needs ___ because ___.'],['questions','A.ii','What will I find out?','Rank two questions and name a source for each.','1. ___ Source ___. 2. ___ Source ___.'],['existing','A.iii','Look at one existing solution','Describe two features of a real bridge model or building guide.','Feature ___ helps ___. Another feature ___ helps ___.'],['findings','A.iv','What did I find out?','Link two source-labelled findings to design choices.','Finding ___ → choice ___. Finding ___ → choice ___.']];
function boardPage(){const [k,tag,title,help,frame]=boardParts[boardCursor];return `<div class="page-heading"><div><div class="eyebrow">MY RESEARCH BOARD · CRITERION A</div><h1>Find out before you build</h1></div><button class="btn secondary small-btn" data-action="print-board">Print my board</button></div><nav class="stage-tabs" aria-label="Research board sections">${['Who?','Find out','Look closely','Make links'].map((x,i)=>`<button data-action="board-step" data-index="${i}" class="${boardCursor===i?'active':''}">${icon(['hand','question','eye','repeat'][i])}<span>${x}</span></button>`).join('')}</nav><section class="stage-panel"><div class="task-heading"><span class="stage-kicker">${tag}</span><span class="pill-counter">${boardCursor+1}/4</span></div><div class="show-prompt">${icon(['hand','question','eye','repeat'][boardCursor])}<h2>${title}</h2></div><p>${help}</p>${field('board-'+k,'My notes',state.board[k]||'',frame,`data-board="${k}"`)}<div class="stage-controls"><button class="btn secondary" data-action="board-prev" ${boardCursor===0?'disabled':''}>← Back</button>${boardCursor<3?'<button class="btn big-start" data-action="board-next">Next part →</button>':'<a class="btn big-start" href="#lesson/13">Use my findings →</a>'}</div></section><p class="quiet-footer">Add drawings, photos and source arrows to your paper board or school portfolio. This page saves your notes.</p>`;}

function evidencePage(){const n=lessons.filter(l=>l.id<=22&&state.answers[l.id]?.ready).length;return `<div class="page-heading"><div><div class="eyebrow">YOUR THINKING COUNTS</div><h1>My evidence</h1><p>Keep your own decisions, checks and changes. Share the exported evidence through your teacher’s approved school system.</p></div></div><div class="evidence-summary"><div><strong>${n} of 22 lessons ready for teacher review</strong><p>This is a self-recorded progress tracker, not an assessment result.</p></div><div class="actions"><button class="btn" data-action="export">Export backup</button><button class="btn secondary" data-action="print-all">Print my evidence</button></div></div><div class="actions"><button class="text-link" data-action="import">Restore a backup</button><button class="text-link" data-action="reset">Reset this device’s workbook</button></div><p class="small">Backups include written notes, route choices and test logs. Use fictional task codes and no personal information. Work is not synchronised across devices.</p><section class="card">${lessons.map(l=>{const a=state.answers[l.id],count=l.fields.filter(f=>a?.fields?.[f.id]?.trim()||a?.oral?.includes(f.id)).length;return `<div class="evidence-item"><span class="num">${String(l.id).padStart(2,'0')}</span><div class="grow"><a href="#lesson/${l.id}">${esc(l.short)}</a><small>${count}/${l.fields.length} response sections · ${esc(routes[a?.route]||'Not started')}${l.kind==='reserve'?' · reserve':''}</small></div><span class="saved-pill">${a?.ready?'Ready for review':count?'Working':'Not started'}</span></div>`;}).join('')}</section>${footer()}`;}
function teacherPage(){return `<div class="page-heading"><div><div class="eyebrow">CURRICULUM & ACCESS</div><h1>Teacher guide</h1><p>All 20 ADEK lessons retain their order and outcomes. The bridge gives the learning a practical context.</p></div></div><div class="actions"><a class="btn" href="resources/adek-grade6-teacher-pack.pdf" target="_blank" rel="noopener">Open original Teacher Pack ↗</a><a class="btn secondary" href="resources/unit-plan.docx" download>Download unit plan</a><button class="btn secondary" data-action="print-teacher">Print route guide</button></div><div class="note important">The original pack is titled Main Course, Term 1; the school plan places it in Term 2. The separate issued Student Lesson Content and Student Worksheets were not available here. The site’s explanations, examples and worksheets are classroom adaptations aligned to the Teacher Pack, not issued ADEK worksheets. Staff resources contain guidance and model responses; this static site has no staff-only access control.</div>
 <div class="grid"><article class="card"><span class="tag">GUIDED · SEN ACCESS</span><h3>Keep the goal, change the access</h3><p>Chunk instructions, offer pictures and words, read-aloud, oral rehearsal, sentence starters, a reader/scribe and practical support. Keep required quantities: six test inputs, at least five retests and individual reasoning.</p></article><article class="card"><span class="tag">INDEPENDENT</span><h3>Fade the scaffolds</h3><p>Use the full checklist and editable evidence sheet. Sentence starters remain available. Choose support by task and learner need; routes are not diagnoses or fixed ability groups.</p></article><article class="card"><span class="tag lab">STRETCH · G&T DEPTH</span><h3>Increase reasoning and transfer</h3><p>Use counterexamples, controlled comparisons, boundary cases, limitations and transfer. Finish shared evidence first. Extension is not extra repetition or an automatic higher grade.</p></article></div>
 <div class="section-heading"><h2>Plan reasonable adjustments</h2></div><div class="learning-block"><p>Record the learner’s agreed support, response mode, adult help and review point in the school system. Offer extra processing time and, where the arrangement requires it, additional project time beyond the normal allocation. Do not assume reserve periods alone provide an entitled adjustment. Preserve individual judgement and distinguish independent work from assistance.</p><p>Use the school’s year overview to check that every MYP Design strand is assessed at least twice across the required programme/year. This site supplies evidence opportunities for this project; it does not certify the school’s annual assessment coverage.</p></div>
 <div class="section-heading"><h2>Full lesson content and activity references</h2></div><section class="learning-block">${lessons.map(x=>`<details id="teacher-lesson-${x.id}"><summary>L${x.id} · ${esc(x.title)}</summary><p>${esc(x.teach)}</p><h3>Learning outcomes</h3><ul>${x.success.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${x.example?.body?`<h3>Worked example</h3><p>${esc(x.example.body)}</p>`:''}${(x.materials||[]).map(m=>`<h3>${esc(m.title)}</h3><p>${esc(m.body)}</p>`).join('')}<h3>${x.kind==='adek'?'Full ADEK task sequence':'Practical task sequence'}</h3><ol>${x.originalSteps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><strong>Access:</strong> ${esc(x.access)}</p><p><strong>Stretch:</strong> ${esc(x.stretch)}</p>${source(x)}</details>`).join('')}</section><div class="section-heading"><h2>Source-aligned lesson and route map</h2></div><div class="table-wrap"><table class="teacher-table"><thead><tr><th>Lesson / source</th><th>Core outcome and evidence</th><th>Guided adjustments</th><th>Stretch challenge</th></tr></thead><tbody>${lessons.filter(l=>l.kind==='adek').map(l=>`<tr><td><a href="#lesson/${l.id}">L${l.id} · W${l.week} ${l.type}</a><br><a href="resources/adek-grade6-teacher-pack.pdf#page=${l.page}" target="_blank" rel="noopener">PDF p. ${l.page}</a><br><span class="tag">${l.strand}</span></td><td><strong>${esc(l.title)}</strong><br>${esc(l.success.join(' '))}</td><td>${esc(l.access)}</td><td>${esc(l.stretch)}</td></tr>`).join('')}</tbody></table></div>
 <div class="grid two"><section class="learning-block"><h2>Assessment checkpoints</h2><p><strong>L14:</strong> F1 A/B plan and pressure test.<br><strong>L18:</strong> F2 C/D build, testing and risk.<br><strong>L19:</strong> original ADEK four-strand assessment.<br><strong>L20:</strong> S1 A/B portfolio.<br><strong>L22:</strong> S2 C/D product and evaluation.</p><p class="small">Mark A, B, C and D separately out of 8 using the school’s Year 1 descriptors. ADEK strand judgements remain separate. A failed prototype can still generate strong evaluation evidence.</p></section><section class="learning-block"><h2>Delivery and Ramadan pacing</h2><p>Follow Core → Lab for each pack week. A 55-minute period allows the original 45-minute structure plus 10 minutes for access or linked evidence. Ramadan period lengths and the planned 8–12 March break need school confirmation. Do not treat the 30-minute essential route as proof that all original work fits.</p><p class="small">L21–22 add making/testing; L23–24 are reserves. Prioritise incomplete ADEK work and agreed access arrangements. No food examples are used in the student activities.</p></section></div>
 <section class="learning-block"><h2>What the technology does</h2><p>The prompt builder constructs text only. Live AI is teacher-mediated; no AI account or API key is needed by students. The small classifier is a transparent numeric demonstration. Practice outputs are fixed and labelled. No camera, student recording, external analytics or submission server is used.</p><p>Text and self-recorded progress stay in this browser. Export/restore moves the workbook; it does not create a teacher dashboard. On shared devices, export then reset. Read-aloud depends on the device’s available browser voices.</p></section>${footer()}`;}
function render(){if('speechSynthesis'in window)window.speechSynthesis.cancel();const [page,id]=location.hash.replace(/^#/,'').split('/');const p=page||'home';let html;if(p==='lesson'){const l=lessons.find(x=>x.id===Number(id));html=l?lessonPage(l):'<div class="empty"><h1>Lesson not found</h1><a href="#lessons">Open all lessons</a></div>';}else html=({home,lessons:lessonsPage,tools:()=>toolsPage(id),board:boardPage,evidence:evidencePage,teacher:teacherPage}[p]||home)();main.innerHTML=html;document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===(p==='lesson'?'lessons':p)));document.title=(p==='lesson'?`Lesson ${id}`:p.charAt(0).toUpperCase()+p.slice(1))+' · AI Build Lab';if(p==='lessons')filterLessons();updatePrompt();updateRisk();updateBridge();updateProgress();settings();window.scrollTo(0,0);if(p==='teacher'&&Number(id)){const panel=document.getElementById('teacher-lesson-'+Number(id));if(panel){panel.open=true;panel.scrollIntoView({block:'start'});}}}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyText(t){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(t);toast('Copied. Give the prompt to your teacher to run.');return;}}catch(e){}const x=document.createElement('textarea');x.value=t;x.style.position='fixed';x.style.left='-9999px';document.body.append(x);x.select();let ok=false;try{ok=document.execCommand('copy');}catch(e){}x.remove();toast(ok?'Copied. Give the prompt to your teacher.':'Copy is unavailable. Select and copy the prompt preview manually.');}
function printable(title,body){const w=window.open('','_blank');if(!w){toast('Allow the print window, or use your browser’s Print option.');return;}w.document.write(`<!doctype html><html><head><title>${esc(title)}</title><meta charset="utf-8"><style>body{font:12pt Arial,sans-serif;line-height:1.55;margin:22mm;color:#152e2c}h1{font-size:23pt}h2{font-size:17pt;margin-top:25px}h3{font-size:12pt}section{break-inside:avoid;margin:18px 0}p{white-space:pre-wrap}table{border-collapse:collapse;width:100%;font-size:10pt}td,th{border:1px solid #aaa;padding:7px;text-align:left;vertical-align:top}small{color:#455b52}.board{display:grid;grid-template-columns:1fr 1fr;gap:15px}.box{border:1px solid #aaa;padding:15px;min-height:220px}.answer{border-left:2px solid #b5cbbd;padding-left:14px;min-height:40px}.lesson{break-before:page}.lesson:first-of-type{break-before:auto}@page{margin:15mm}</style></head><body><h1>${esc(title)}</h1>${body}<footer style="margin-top:30px;border-top:1px solid #aaa;padding-top:10px;font-size:9pt">Made by Ashleigh Lavens · Based on ADEK Grade 6 Main Course, Term 1 Teacher Pack, v4. Classroom adaptations by Ashleigh Lavens; original source credited to ADEK.</footer></body></html>`);w.document.close();w.onload=()=>{w.focus();w.print();};}
function lessonPrint(l){const a=state.answers[l.id]||{fields:{},oral:[],checks:[]};return `<article class="lesson"><h2>L${l.id} · ${esc(l.short)}</h2><p><strong>${esc(l.visual.bite)}</strong></p><h3>Do these steps</h3>${l.visual.steps.map((s,i)=>`<p>${a.checks?.[i]?'☑':'☐'} ${esc(s)}</p>`).join('')}${l.fields.map(f=>`<section><h3>${esc(f.label)}</h3><small>${esc(f.frame)}</small><p class="answer">${esc(a.fields?.[f.id]||'____________________________________________________')}${a.oral?.includes(f.id)?'\nOral evidence agreed with teacher.':''}</p></section>`).join('')}<section><h3>Exit question</h3><p>${esc(l.exit)}</p><p class="answer">${esc(a.fields?.exit||'____________________________________________________')}</p></section>${a.route==='stretch'?`<section><h3>Stretch</h3><p>${esc(l.stretch)}</p><p>${esc(a.fields?.extension||'')}</p></section>`:''}<small>Classroom adaptation · ${l.page?'ADEK Teacher Pack PDF p. '+l.page:'MYP practical'}</small></article>`;}
document.addEventListener('input',e=>{const x=e.target;if(x.id==='lesson-search'){filter.q=x.value;filterLessons();return;}if(x.dataset.answer){const a=answer(x.dataset.lesson);a.fields[x.dataset.answer]=x.value;a.ready=false;save();}if(x.dataset.board){state.board[x.dataset.board]=x.value;save();}if(x.dataset.tool){state.tools[x.dataset.tool]=x.value;save();updatePrompt();updateRisk();updateBridge();}});
document.addEventListener('change',e=>{const x=e.target;if(x.id==='type-filter'){filter.type=x.value;filterLessons();}if(x.id==='strand-filter'){filter.strand=x.value;filterLessons();}if(x.id==='reserve-filter'){filter.reserve=x.checked;filterLessons();}if(x.dataset.check!==undefined){const a=answer(x.dataset.lesson);a.checks[+x.dataset.check]=x.checked;a.ready=false;save();if(document.getElementById('check-count'))document.getElementById('check-count').textContent=`${a.checks.filter(Boolean).length}/${lessons.find(l=>l.id===+x.dataset.lesson).originalSteps.length}`;}if(x.dataset.oral){const a=answer(x.dataset.lesson);a.oral=a.oral.filter(id=>id!==x.dataset.oral);if(x.checked)a.oral.push(x.dataset.oral);a.ready=false;save();}if(x.dataset.exitOral){const a=answer(x.dataset.exitOral);a.exitOral=x.checked;a.ready=false;save();}if(x.dataset.setting){state.settings[x.dataset.setting]=x.checked;settings();save();}if(x.dataset.tool){state.tools[x.dataset.tool]=x.value;save();updatePrompt();updateRisk();updateBridge();}});
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=+b.dataset.id,l=lessons.find(x=>x.id===id);switch(action){
 case'stage':answer(id).stage=+b.dataset.stage;save();render();break;
 case'visual-choice':answer(id).choice=+b.dataset.choice;save();render();break;
 case'task-prev':answer(id).taskIndex=Math.max(0,(answer(id).taskIndex||0)-1);save();render();break;
 case'task-jump':answer(id).taskIndex=+b.dataset.task;save();render();break;
 case'task-done':{const a=answer(id),n=a.taskIndex||0;a.checks[n]=true;a.ready=false;if(n<l.originalSteps.length-1)a.taskIndex=n+1;else a.stage=3;save();render();break;}
 case'evidence-prev':answer(id).fieldIndex=Math.max(0,(answer(id).fieldIndex||0)-1);save();render();break;
 case'evidence-next':answer(id).fieldIndex=Math.min(l.fields.length,(answer(id).fieldIndex||0)+1);save();render();break;
 case'material-prev':answer(id).cardIndex=Math.max(0,(answer(id).cardIndex||0)-1);save();render();{const d=document.querySelector('.help-drawer');if(d){d.open=true;d.scrollIntoView({block:'center'});}}break;
 case'material-next':answer(id).cardIndex=Math.min(+b.dataset.max,(answer(id).cardIndex||0)+1);save();render();{const d=document.querySelector('.help-drawer');if(d){d.open=true;d.scrollIntoView({block:'center'});}}break;
 case'help-prompt':toast('Show your current step to a partner or teacher. Ask for a reader, scribe or practical help.');break;
 case'prompt-prev':promptCursor=Math.max(0,promptCursor-1);render();break;
 case'prompt-next':promptCursor=Math.min(5,promptCursor+1);render();break;
 case'board-step':boardCursor=+b.dataset.index;render();break;
 case'board-prev':boardCursor=Math.max(0,boardCursor-1);render();break;
 case'board-next':boardCursor=Math.min(3,boardCursor+1);render();break;
 case'task-undo':answer(id).checks[answer(id).taskIndex||0]=false;answer(id).ready=false;save();render();break;
 case'access':document.getElementById('access-dialog').showModal();break;
 case'close-access':document.getElementById('access-dialog').close();break;
 case'route':answer(id).route=b.dataset.route;state.route=b.dataset.route;save();render();toast(`${routes[b.dataset.route]} route opened. Your answers are kept.`);break;
 case'ready':{const a=answer(id);if(l.fields.some(f=>!a.fields[f.id]?.trim()&&!a.oral.includes(f.id))||(!a.fields.exit?.trim()&&!a.exitOral)){toast('Add each response or agree an oral evidence record, including the exit explanation.');break;}if(l.originalSteps.some((_,i)=>!a.checks[i])){toast('Complete and tick each required task step before recording ready for review.');break;}a.ready=true;save();render();toast('Saved as ready for teacher review. This is not a grade.');break;}
 case'unready':answer(id).ready=false;save();render();break;
 case'speak':if(!('speechSynthesis'in window)){toast('Read-aloud is not available here. Ask a partner or teacher to read with you.');break;}if(speechSynthesis.speaking){speechSynthesis.cancel();b.textContent='▷ Read this step';b.classList.remove('reader-active');break;}const u=new SpeechSynthesisUtterance(stageSpeak(l));u.lang='en-GB';u.rate=.88;u.onend=()=>{b.textContent='▷ Read this step';b.classList.remove('reader-active');};u.onerror=()=>{b.textContent='▷ Read this step';b.classList.remove('reader-active');toast('The device could not read this aloud. Ask for a reader.');};b.textContent='■ Stop reading';b.classList.add('reader-active');speechSynthesis.speak(u);break;
 case'export':download('ai-build-lab-backup.json',JSON.stringify(state,null,2),'application/json');toast('Backup downloaded. Keep it in your approved school storage.');break;
 case'import':document.getElementById('import-file').click();break;
 case'reset':if(confirm('Export a backup first. Resetting removes this browser’s workbook, including all lesson notes and logs. Continue?')){state=fresh();save();render();toast('Workbook reset.');}break;
 case'model':trainModel(b.dataset.profile);break;
 case'copy-prompt':await copyText(promptText());break;
 case'rule-check':case'triage-check':document.getElementById(b.dataset.target).textContent=(b.dataset.choice===b.dataset.correct?'That matches the evidence. ':'Try the evidence again. ')+b.dataset.reason;break;
 case'practice-output':document.getElementById('practice-output').textContent=b.dataset.version==='weak'?'FIXED PRACTICE OUTPUT A\nReference: six plates, no cardboard; connection not identified.\n“Use eight plates and a cardboard deck. Attach it there. It will definitely hold.”\nCheck the count, missing material, unclear location and unsupported claim.':'FIXED PRACTICE OUTPUT B\nSame reference: six plates, no cardboard.\n“Use only the six recorded plates. Compare the proposed joint with the approved sketch and ask the teacher to identify it before building. Check the gap and vehicle fit, then run the physical crossing test.”\nThis fixes some issues; it is not a complete or physically validated bridge plan.';break;
 case'print-lesson':printable(`AI Build Lab · Lesson ${id}`,lessonPrint(l));break;
 case'print-all':printable('My AI Build Lab evidence',`<p>Self-recorded work. Teacher assessment is separate.</p>${lessons.filter(l=>state.answers[l.id]&&Object.values(state.answers[l.id].fields||{}).some(v=>v.trim())||state.answers[l.id]?.oral?.length).map(lessonPrint).join('')||'<p>No written or oral evidence records yet.</p>'}<h2>Research board</h2>${boardParts.map(([k,t,title])=>`<h3>${t} ${title}</h3><p>${esc(state.board[k]||'')}</p>`).join('')}<h2>Workbench records</h2>${toolKeys.filter(k=>state.tools[k]).map(k=>`<h3>${esc(k)}</h3><p>${esc(state.tools[k])}</p>`).join('')}`);break;
 case'print-board':printable('My Criterion A research board',`<div class="board">${boardParts.map(([k,t,title,help,frame])=>`<section class="box"><h2>${t} · ${title}</h2><small>${help}<br>${frame}</small><p>${esc(state.board[k]||'[Add your notes and evidence references]')}</p></section>`).join('')}</div><p>Add a drawing/photo and arrows from source-labelled findings to choices on your paper board.</p>`);break;
 case'print-teacher':printable('Teacher route and source map',`<p>Guided routes support access; Stretch routes add depth. Shared outcomes and required evidence are retained. Use agreed extra time beyond the normal project allocation where required. See the full guide for source and delivery notes.</p><table><thead><tr><th>ADEK lesson</th><th>Guided / SEN access</th><th>Stretch / G&T depth</th></tr></thead><tbody>${lessons.filter(x=>x.kind==='adek').map(x=>`<tr><td>L${x.id} ${esc(x.title)}<br>PDF p. ${x.page}</td><td>${esc(x.access)}</td><td>${esc(x.stretch)}</td></tr>`).join('')}</tbody></table>`);break;
 }});
document.getElementById('import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('Backup is too large.');const restored=cleanState(JSON.parse(await f.text()));if(!confirm('Replace this device’s current workbook with the backup? Export current work first if you need it.'))return;state=restored;save();render();toast('Backup restored.');}catch(err){toast('Could not restore: '+err.message);}finally{e.target.value='';}});
window.addEventListener('hashchange',render);render();if(!storageOK)toast('Saved work could not be loaded. Export new work before leaving this page.');
})();
